"""RetinaScan XAI: export real IDRiD sample photos for the demo (generated by build_kernel.py --stage samples).

IDRiD is CC BY 4.0, so a few images may be redistributed with attribution. Picks the first
N official TEST-set images of each grade (deterministic, not chosen by model output),
resizes to 1024 px and writes samples.csv with the official grade plus the licence files.
"""
import csv
import json
import shutil
from pathlib import Path

import cv2

CONFIG = json.loads(r'''__CONFIG__''')
CODE_B64 = "__CODE_B64__"  # unused; keeps the template contract
OUT = Path("/kaggle/working/samples")


def main():
    OUT.mkdir(parents=True, exist_ok=True)
    labels = sorted(Path("/kaggle/input").rglob("*Disease Grading_Testing Labels.csv"))
    if not labels:
        raise SystemExit("IDRiD testing labels not found")
    root = labels[0].parents[1]  # .../B. Disease Grading
    img_dir = next(d for d in root.rglob("b. Testing Set") if d.parent.name == "1. Original Images")
    rows = list(csv.reader(open(labels[0], encoding="utf-8-sig")))
    head = rows[0]
    ni = next(i for i, h in enumerate(head) if "image" in h.lower())
    gi = next(i for i, h in enumerate(head) if "retinopathy" in h.lower())
    per = {int(g): int(n) for g, n in CONFIG["per_grade"].items()}
    picked, count = [], {g: 0 for g in per}
    for r in rows[1:]:
        if not r or not r[ni].strip():
            continue
        name, grade = r[ni].strip(), int(r[gi])
        if count.get(grade, 99) < per.get(grade, 0):
            count[grade] += 1
            picked.append((name, grade))
    with open(OUT / "samples.csv", "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["file", "idrid_image", "official_grade", "split"])
        for name, grade in picked:
            img = cv2.imread(str(img_dir / f"{name}.jpg"))
            s = CONFIG["side"] / max(img.shape[:2])
            img = cv2.resize(img, None, fx=s, fy=s, interpolation=cv2.INTER_AREA)
            fn = f"idrid_test_{name}.jpg"
            cv2.imwrite(str(OUT / fn), img, [cv2.IMWRITE_JPEG_QUALITY, 90])
            w.writerow([fn, name, grade, "IDRiD official test set"])
    for lic in ("LICENSE.txt", "CC-BY-4.0.txt"):
        src = next(root.rglob(lic), None) or next(root.parent.rglob(lic), None)
        if src:
            shutil.copy(src, OUT / lic)
    print("exported", picked, flush=True)


if __name__ == "__main__":
    main()
